var j = items[0].json;
var raw = '';
if (typeof j === 'string') { raw = j; }
else if (j && typeof j.data === 'string') { raw = j.data; }
else if (j && typeof j.body === 'string') { raw = j.body; }
else if (j) { for (var k in j) { if (typeof j[k] === 'string' && j[k].indexOf(',') >= 0) { raw = j[k]; break; } } }

var lines = raw.split(/\r?\n/).filter(function(l) { return l.trim(); });
if (lines.length < 1) { return [{ json: { Topic: '' } }]; }

function parseCSVLine(line) {
  var result = [];
  var current = '';
  var inQuotes = false;
  for (var i = 0; i < line.length; i++) {
    var ch = line[i];
    if (ch === '"') { inQuotes = !inQuotes; }
    else if (ch === ',' && !inQuotes) { result.push(current.trim()); current = ''; }
    else { current += ch; }
  }
  result.push(current.trim());
  return result;
}

var rows = [];
for (var i = 0; i < lines.length; i++) {
  var vals = parseCSVLine(lines[i]);
  if (vals[0] && vals[0].trim()) {
    rows.push({ Topic: vals[0] || '', Tone: vals[1] || 'professional', Audience: vals[2] || 'professionals' });
  }
}

if (rows.length === 0) { return [{ json: { Topic: '' } }]; }

// Post topics in file order, skipping ones already published.
// Published topics are remembered in workflow static data by the
// "Mark Topic Posted" node (saved only for runs of the ACTIVE workflow).
var store = getWorkflowStaticData('global');
var posted = store.postedTopics || [];
var postedSet = {};
for (var p = 0; p < posted.length; p++) { postedSet[posted[p].toLowerCase()] = true; }

var picked = null;
for (var r = 0; r < rows.length; r++) {
  if (!postedSet[rows[r].Topic.toLowerCase()]) { picked = rows[r]; picked._position = r + 1; break; }
}
if (!picked) { return [{ json: { Topic: '', _reason: 'All ' + rows.length + ' topics have been posted' } }]; }

picked._totalTopics = rows.length;
picked._postedSoFar = posted.length;
return [{ json: picked }];

