// Turns the OpenAI reply into a LinkedIn Posts API request body.
// LinkedIn "little" text format: reserved characters must be escaped with a
// backslash or the post gets truncated/rejected. Hashtags become
// {hashtag|\#|Tag} templates so they stay clickable.

// >>> Your LinkedIn member URN (from GET https://api.linkedin.com/v2/userinfo -> "sub")
const AUTHOR_URN = 'urn:li:person:EGqD78qR46';

const MAX_CHARS = 2900; // LinkedIn commentary limit is 3000

let raw = (($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '').trim();
raw = raw.replace(/^```[a-z]*\n?|\n?```$/g, '').trim();
if (!raw) {
  throw new Error('OpenAI returned no post text');
}
// Bold header: the topic from the CSV. LinkedIn has no bold formatting, so
// letters and digits are mapped to Unicode Mathematical Sans-Serif Bold.
const toBold = (s) => Array.from(s).map((ch) => {
  const c = ch.codePointAt(0);
  if (c >= 65 && c <= 90) return String.fromCodePoint(0x1D5D4 + c - 65);   // A-Z
  if (c >= 97 && c <= 122) return String.fromCodePoint(0x1D5EE + c - 97);  // a-z
  if (c >= 48 && c <= 57) return String.fromCodePoint(0x1D7EC + c - 48);   // 0-9
  return ch;
}).join('');
// Topic-matched emoji in front of the bold header (first keyword match wins).
const EMOJI_RULES = [
  [/\b(ai|llms?|gpt|genai|machine learning|ml|agents?|agentic|rag|prompts?|prompting|embeddings?|vector|copilot|mcp|chatbot|multi model|gpu)\b/i, '🤖'],
  [/(secur|auth|jwt|oauth|encrypt|owasp|vulnerab|token|identity|zero trust|threat|ddos|bot detection|hacking|compliance|gdpr|rbac|abac|secret)/i, '🔐'],
  [/(incident|postmortem|root cause|disaster|recovery|resilien|fault|failover|backup|retry|circuit breaker|backpressure|outage|rollback)/i, '🛡️'],
  [/(cach|redis|cdn)/i, '⚡'],
  [/(database|sql|nosql|index|query|mongo|postgres|cosmos|shard|replica|replication|transaction|storage|acid|olap|oltp|etl|elt|data lake|warehous|schema|archiv|dataset|elasticsearch|full text search|connection pool)/i, '🗄️'],
  [/(docker|kubernetes|k8s|container|devops|ci cd|ci\/cd|pipeline|deploy|argo|flux|gitops|terraform|helm|infrastructure|configmap|build)/i, '🐳'],
  [/(cloud|azure|aws|gcp|serverless)/i, '☁️'],
  [/(monitor|observab|logging|tracing|metrics|alert)/i, '📊'],
  [/(real time|realtime|websocket|signalr|stream)/i, '📡'],
  [/(microservice|distributed|kafka|queue|event|messag|saga|cap theorem|consistency|partition|load balanc|cqrs|idempoten|edge computing|large systems)/i, '🧩'],
  [/(ui|ux|frontend|front end|ssr|csr|ssg|lazy loading|code splitting|accessibility|progressive web|offline first|storybook|infinite scroll|react|angular|blazor|voice|slow network|edge rendering)/i, '🎨'],
  [/(test|tdd|quality|bug|debug|code review)/i, '🧪'],
  [/(perform|latency|scal|async|parallel|concurren|throughput|optimi|protobuf)/i, '🚀'],
  [/(api|rest|graphql|grpc|endpoint|http|pagination|webhook|versioning)/i, '🔌'],
  [/(pattern|solid|architect|design|clean code|refactor|principle|ddd|aggregate|bounded context|coupling|factory|singleton|dependency injection|god object|domain|maintainable|technical debt)/i, '🏛️'],
  [/(blog|writing|documentation|branding|linkedin|portfolio|open source)/i, '✍️'],
  [/(learn|staying updated|mindset|burnout|career|growth|habit|senior|junior)/i, '🌱'],
  [/(lead|team|manag|mentor|decision|communicat|time|productiv|priorit|roadmap|engineer|hiring|interview)/i, '🧭'],
];
const FALLBACK_EMOJI = ['✨', '💡', '🎯', '📌', '🧠'];
const pickEmoji = (t) => {
  for (const [re, e] of EMOJI_RULES) { if (re.test(t)) return e; }
  let h = 0; for (const ch of t) h = (h * 31 + ch.codePointAt(0)) >>> 0;
  return FALLBACK_EMOJI[h % FALLBACK_EMOJI.length];
};

const topic = (($('Parse CSV').first().json.Topic) || '').trim();
if (topic) {
  raw = pickEmoji(topic) + ' ' + toBold(topic) + '\n\n' + raw;
}

if (raw.length > MAX_CHARS) {
  const cut = raw.lastIndexOf('\n', MAX_CHARS);
  raw = raw.slice(0, cut > 0 ? cut : MAX_CHARS).trim();
}

const escapeLittle = (s) => s.replace(/[\\|{}@\[\]()<>#*_~]/g, (c) => '\\' + c);

const tags = [];
let text = raw.replace(/#([\p{L}\p{N}_]+)/gu, (m, tag) => {
  tags.push(tag);
  return '\u0000' + (tags.length - 1) + '\u0000';
});
text = escapeLittle(text);
text = text.replace(/\u0000(\d+)\u0000/g, (m, i) => '{hashtag|\\#|' + escapeLittle(tags[Number(i)]) + '}');

return [{
  json: {
    postText: raw,
    body: {
      author: AUTHOR_URN,
      commentary: text,
      visibility: 'PUBLIC',
      distribution: {
        feedDistribution: 'MAIN_FEED',
        targetEntities: [],
        thirdPartyDistributionChannels: []
      },
      lifecycleState: 'PUBLISHED',
      isReshareDisabledByAuthor: false
    }
  }
}];

// Runs only after LinkedIn accepted the post: remember the topic so it is not posted again.
const store = $getWorkflowStaticData('global');
const topic = $('Parse CSV').first().json.Topic;
store.postedTopics = store.postedTopics || [];
if (!store.postedTopics.some(t => t.toLowerCase() === topic.toLowerCase())) {
  store.postedTopics.push(topic);
}
return $input.all();
